export const pcbAccelerometerByModel = new Map(pcbAccelerometers.map(sensor => [sensor.model, sensor]));
export const pcbAccelerometerOptions = pcbAccelerometers.map(sensor => ({ value: sensor.model, label: `${sensor.model} · ${sensor.sensitivityValue ?? '—'} ${sensor.sensitivityUnit || ''} · ${sensor.measurementRangeGPeak ?? '—'} g`, group: sensor.family }));
